sys_ux_data_broker_transform.script:
function transform(input) {
 var filter = input.filter;

   var gr = new GlideRecord('sys_filter');
gr.addEncodedQuery('titleSTARTSWITH'+filter);
gr.query();

var finalResult = [];

if (gr.next()) {
    var filterValue = gr.getValue('filter'); // Retrieve the 'filter' field value

    // Parse the filter for 'nameIN' and extract the values
    var match = filterValue.match(/nameIN([^\\^]+)/);

    if (match && match[1]) {
        // Split the extracted part by commas and store in the result array
        var extractedValues = match[1].split(',');

        // Convert extracted values to the desired structure
        finalResult = extractedValues.map(value => [
            {
                id: value,
                label: value
            }
        ]);
    } else {
        gs.print("No 'nameIN' match found in the filter value");
    }
} else {
    gs.print("No Data Found");
}

// Log the final result
gs.print("Final Result: " + JSON.stringify(finalResult));
 return finalResult ;

}
